INSERT INTO "public"."heartbeat_runs" ("id", "company_id", "agent_id", "invocation_source", "status", "started_at", "finished_at", "error", "external_run_id", "context_snapshot", "created_at", "updated_at", "trigger_detail", "wakeup_request_id", "exit_code", "signal", "usage_json", "result_json", "session_id_before", "session_id_after", "log_store", "log_ref", "log_bytes", "log_sha256", "log_compressed", "stdout_excerpt", "stderr_excerpt", "error_code", "process_pid", "process_started_at", "retry_of_run_id", "process_loss_retry_count") VALUES ($paperclip$ede93ab3-5f8c-4b37-89cd-a537427ddec9$paperclip$, $paperclip$d0cfa69a-7d52-4b25-9f15-2cb36c1effb2$paperclip$, $paperclip$f42beb11-de54-4972-9ed8-5486b8d58868$paperclip$, $paperclip$assignment$paperclip$, $paperclip$succeeded$paperclip$, $paperclip$2026-04-01T02:16:31.313Z$paperclip$, $paperclip$2026-04-01T02:19:46.611Z$paperclip$, NULL, NULL, $paperclip${"source":"issue.create","taskId":"7b0f97ed-1c9e-45b4-aa89-22bf659228c3","issueId":"7b0f97ed-1c9e-45b4-aa89-22bf659228c3","taskKey":"7b0f97ed-1c9e-45b4-aa89-22bf659228c3","projectId":"200f5aa3-58d6-4e70-ac01-b6d6b1c51615","wakeReason":"issue_assigned","wakeSource":"assignment","wakeTriggerDetail":"system","paperclipWorkspace":{"cwd":"C:\\Users\\THANHSANG\\.paperclip\\instances\\default\\projects\\d0cfa69a-7d52-4b25-9f15-2cb36c1effb2\\200f5aa3-58d6-4e70-ac01-b6d6b1c51615\\_default","mode":"shared_workspace","source":"project_primary","repoRef":null,"repoUrl":null,"strategy":"project_primary","agentHome":"C:\\Users\\THANHSANG\\.paperclip\\instances\\default\\workspaces\\f42beb11-de54-4972-9ed8-5486b8d58868","projectId":"200f5aa3-58d6-4e70-ac01-b6d6b1c51615","branchName":null,"workspaceId":null,"worktreePath":null},"paperclipWorkspaces":[],"executionWorkspaceId":"54f63369-9d89-4533-ae3d-f774b4cf8352"}$paperclip$, $paperclip$2026-04-01T02:08:41.402Z$paperclip$, $paperclip$2026-04-01T02:19:46.611Z$paperclip$, $paperclip$system$paperclip$, $paperclip$39237ea0-d567-47b5-9acf-f77893986301$paperclip$, 0, NULL, $paperclip${"model":"github-copilot/claude-sonnet-4.6","biller":"github-copilot","costUsd":0,"provider":"github-copilot","billingType":"unknown","inputTokens":60799,"freshSession":true,"outputTokens":6953,"sessionReused":false,"rawInputTokens":60799,"sessionRotated":false,"rawOutputTokens":6953,"cachedInputTokens":1109295,"taskSessionReused":false,"persistedSessionId":"ses_2b92bb7deffeRmQyeAUSbdDy5O","rawCachedInputTokens":1109295,"sessionRotationReason":null}$paperclip$, $paperclip${"stderr":"","stdout":"{\"type\":\"step_start\",\"timestamp\":1775009814842,\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"part\":{\"id\":\"prt_d46d45936001FvUs1OgynTlirf\",\"messageID\":\"msg_d46d448f20012maxljtSGBNqGb\",\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"snapshot\":\"f3d0e34592e5a1072f75b301c48334f921a480e9\",\"type\":\"step-start\"}}\r\n{\"type\":\"tool_use\",\"timestamp\":1775009814850,\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"part\":{\"id\":\"prt_d46d45938001VUW3gG8ktFXRla\",\"messageID\":\"msg_d46d448f20012maxljtSGBNqGb\",\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"type\":\"tool\",\"tool\":\"skill\",\"callID\":\"tooluse_MPeHziC3VUGMHFRCHMhkDR\",\"state\":{\"status\":\"completed\",\"input\":{\"name\":\"paperclip\"},\"output\":\"<skill_content name=\\\"paperclip\\\">\\n# Skill: paperclip\\n\\n# Paperclip Skill\\r\\n\\r\\nYou run in **heartbeats** — short execution windows triggered by Paperclip. Each heartbeat, you wake up, check your work, do something useful, and exit. You do not run continuously.\\r\\n\\r\\n## Authentication\\r\\n\\r\\nEnv vars auto-injected: `PAPERCLIP_AGENT_ID`, `PAPERCLIP_COMPANY_ID`, `PAPERCLIP_API_URL`, `PAPERCLIP_RUN_ID`. Optional wake-context vars may also be present: `PAPERCLIP_TASK_ID` (issue/task that triggered this wake), `PAPERCLIP_WAKE_REASON` (why this run was triggered), `PAPERCLIP_WAKE_COMMENT_ID` (specific comment that triggered this wake), `PAPERCLIP_APPROVAL_ID`, `PAPERCLIP_APPROVAL_STATUS`, and `PAPERCLIP_LINKED_ISSUE_IDS` (comma-separated). For local adapters, `PAPERCLIP_API_KEY` is auto-injected as a short-lived run JWT. For non-local adapters, your operator should set `PAPERCLIP_API_KEY` in adapter config. All requests use `Authorization: Bearer $PAPERCLIP_API_KEY`. All endpoints under `/api`, all JSON. Never hard-code the API URL.\\r\\n\\r\\nManual local CLI mode (outside heartbeat runs): use `paperclipai agent local-cli <agent-id-or-shortname> --company-id <company-id>` to install Paperclip skills for Claude/Codex and print/export the required `PAPERCLIP_*` environment variables for that agent identity.\\r\\n\\r\\n**Run audit trail:** You MUST include `-H 'X-Paperclip-Run-Id: $PAPERCLIP_RUN_ID'` on ALL API requests that modify issues (checkout, update, comment, create subtask, release). This links your actions to the current heartbeat run for traceability.\\r\\n\\r\\n## The Heartbeat Procedure\\r\\n\\r\\nFollow these steps every time you wake up:\\r\\n\\r\\n**Step 1 — Identity.** If not already in context, `GET /api/agents/me` to get your id, companyId, role, chainOfCommand, and budget.\\r\\n\\r\\n**Step 2 — Approval follow-up (when triggered).** If `PAPERCLIP_APPROVAL_ID` is set (or wake reason indicates approval resolution), review the approval first:\\r\\n\\r\\n- `GET /api/approvals/{approvalId}`\\r\\n- `GET /api/approvals/{approvalId}/issues`\\r\\n- For each linked issue:\\r\\n  - close it (`PATCH` status to `done`) if the approval fully resolves requested work, or\\r\\n  - add a markdown comment explaining why it remains open and what happens next.\\r\\n    Always include links to the approval and issue in that comment.\\r\\n\\r\\n**Step 3 — Get assignments.** Prefer `GET /api/agents/me/inbox-lite` for the normal heartbeat inbox. It returns the compact assignment list you need for prioritization. Fall back to `GET /api/companies/{companyId}/issues?assigneeAgentId={your-agent-id}&status=todo,in_progress,blocked` only when you need the full issue objects.\\r\\n\\r\\n**Step 4 — Pick work (with mention exception).** Work on `in_progress` first, then `todo`. Skip `blocked` unless you can unblock it.\\r\\n**Blocked-task dedup:** Before working on a `blocked` task, fetch its comment thread. If your most recent comment was a blocked-status update AND no new comments from other agents or users have been posted since, skip the task entirely — do not checkout, do not post another comment. Exit the heartbeat (or move to the next task) instead. Only re-engage with a blocked task when new context exists (a new comment, status change, or event-based wake like `PAPERCLIP_WAKE_COMMENT_ID`).\\r\\nIf `PAPERCLIP_TASK_ID` is set and that task is assigned to you, prioritize it first for this heartbeat.\\r\\nIf this run was triggered by a comment mention (`PAPERCLIP_WAKE_COMMENT_ID` set; typically `PAPERCLIP_WAKE_REASON=issue_comment_mentioned`), you MUST read that comment thread first, even if the task is not currently assigned to you.\\r\\nIf that mentioned comment explicitly asks you to take the task, you may self-assign by checking out `PAPERCLIP_TASK_ID` as yourself, then proceed normally.\\r\\nIf the comment asks for input/review but not ownership, respond in comments if useful, then continue with assigned work.\\r\\nIf the comment does not direct you to take ownership, do not self-assign.\\r\\nIf nothing is assigned and there is no valid mention-based ownership handoff, exit the heartbeat.\\r\\n\\r\\n**Step 5 — Checkout.** You MUST checkout before doing any work. Include the run ID header:\\r\\n\\r\\n```\\r\\nPOST /api/issues/{issueId}/checkout\\r\\nHeaders: Authorization: Bearer $PAPERCLIP_API_KEY, X-Paperclip-Run-Id: $PAPERCLIP_RUN_ID\\r\\n{ \\\"agentId\\\": \\\"{your-agent-id}\\\", \\\"expectedStatuses\\\": [\\\"todo\\\", \\\"backlog\\\", \\\"blocked\\\"] }\\r\\n```\\r\\n\\r\\nIf already checked out by you, returns normally. If owned by another agent: `409 Conflict` — stop, pick a different task. **Never retry a 409.**\\r\\n\\r\\n**Step 6 — Understand context.** Prefer `GET /api/issues/{issueId}/heartbeat-context` first. It gives you compact issue state, ancestor summaries, goal/project info, and comment cursor metadata without forcing a full thread replay.\\r\\n\\r\\nUse comments incrementally:\\r\\n\\r\\n- if `PAPERCLIP_WAKE_COMMENT_ID` is set, fetch that exact comment first with `GET /api/issues/{issueId}/comments/{commentId}`\\r\\n- if you already know the thread and only need updates, use `GET /api/issues/{issueId}/comments?after={last-seen-comment-id}&order=asc`\\r\\n- use the full `GET /api/issues/{issueId}/comments` route only when you are cold-starting, when session memory is unreliable, or when the incremental path is not enough\\r\\n\\r\\nRead enough ancestor/comment context to understand _why_ the task exists and what changed. Do not reflexively reload the whole thread on every heartbeat.\\r\\n\\r\\n**Step 7 — Do the work.** Use your tools and capabilities.\\r\\n\\r\\n**Step 8 — Update status and communicate.** Always include the run ID header.\\r\\nIf you are blocked at any point, you MUST update the issue to `blocked` before exiting the heartbeat, with a comment that explains the blocker and who needs to act.\\r\\n\\r\\nWhen writing issue descriptions or comments, follow the ticket-linking rule in **Comment Style** below.\\r\\n\\r\\n```json\\r\\nPATCH /api/issues/{issueId}\\r\\nHeaders: X-Paperclip-Run-Id: $PAPERCLIP_RUN_ID\\r\\n{ \\\"status\\\": \\\"done\\\", \\\"comment\\\": \\\"What was done and why.\\\" }\\r\\n\\r\\nPATCH /api/issues/{issueId}\\r\\nHeaders: X-Paperclip-Run-Id: $PAPERCLIP_RUN_ID\\r\\n{ \\\"status\\\": \\\"blocked\\\", \\\"comment\\\": \\\"What is blocked, why, and who needs to unblock it.\\\" }\\r\\n```\\r\\n\\r\\nStatus values: `backlog`, `todo`, `in_progress`, `in_review`, `done`, `blocked`, `cancelled`. Priority values: `critical`, `high`, `medium`, `low`. Other updatable fields: `title`, `description`, `priority`, `assigneeAgentId`, `projectId`, `goalId`, `parentId`, `billingCode`.\\r\\n\\r\\n**Step 9 — Delegate if needed.** Create subtasks with `POST /api/companies/{companyId}/issues`. Always set `parentId` and `goalId`. Set `billingCode` for cross-team work.\\r\\n\\r\\n## Project Setup Workflow (CEO/Manager Common Path)\\r\\n\\r\\nWhen asked to set up a new project with workspace config (local folder and/or GitHub repo), use:\\r\\n\\r\\n1. `POST /api/companies/{companyId}/projects` with project fields.\\r\\n2. Optionally include `workspace` in that same create call, or call `POST /api/projects/{projectId}/workspaces` right after create.\\r\\n\\r\\nWorkspace rules:\\r\\n\\r\\n- Provide at least one of `cwd` (local folder) or `repoUrl` (remote repo).\\r\\n- For repo-only setup, omit `cwd` and provide `repoUrl`.\\r\\n- Include both `cwd` + `repoUrl` when local and remote references should both be tracked.\\r\\n\\r\\n## OpenClaw Invite Workflow (CEO)\\r\\n\\r\\nUse this when asked to invite a new OpenClaw employee.\\r\\n\\r\\n1. Generate a fresh OpenClaw invite prompt:\\r\\n\\r\\n```\\r\\nPOST /api/companies/{companyId}/openclaw/invite-prompt\\r\\n{ \\\"agentMessage\\\": \\\"optional onboarding note for OpenClaw\\\" }\\r\\n```\\r\\n\\r\\nAccess control:\\r\\n\\r\\n- Board users with invite permission can call it.\\r\\n- Agent callers: only the company CEO agent can call it.\\r\\n\\r\\n2. Build the copy-ready OpenClaw prompt for the board:\\r\\n\\r\\n- Use `onboardingTextUrl` from the response.\\r\\n- Ask the board to paste that prompt into OpenClaw.\\r\\n- If the issue includes an OpenClaw URL (for example `ws://127.0.0.1:18789`), include that URL in your comment so the board/OpenClaw uses it in `agentDefaultsPayload.url`.\\r\\n\\r\\n3. Post the prompt in the issue comment so the human can paste it into OpenClaw.\\r\\n\\r\\n4. After OpenClaw submits the join request, monitor approvals and continue onboarding (approval + API key claim + skill install).\\r\\n\\r\\n## Company Skills Workflow\\r\\n\\r\\nAuthorized managers can install company skills independently of hiring, then assign or remove those skills on agents.\\r\\n\\r\\n- Install and inspect company skills with the company skills API.\\r\\n- Assign skills to existing agents with `POST /api/agents/{agentId}/skills/sync`.\\r\\n- When hiring or creating an agent, include optional `desiredSkills` so the same assignment model is applied on day one.\\r\\n\\r\\nIf you are asked to install a skill for the company or an agent you MUST read:\\r\\n`skills/paperclip/references/company-skills.md`\\r\\n\\r\\n## Critical Rules\\r\\n\\r\\n- **Always checkout** before working. Never PATCH to `in_progress` manually.\\r\\n- **Never retry a 409.** The task belongs to someone else.\\r\\n- **Never look for unassigned work.**\\r\\n- **Self-assign only for explicit @-mention handoff.** This requires a mention-triggered wake with `PAPERCLIP_WAKE_COMMENT_ID` and a comment that clearly directs you to do the task. Use checkout (never direct assignee patch). Otherwise, no assignments = exit.\\r\\n- **Honor \\\"send it back to me\\\" requests from board users.** If a board/user asks for review handoff (e.g. \\\"let me review it\\\", \\\"assign it back to me\\\"), reassign the issue to that user with `assigneeAgentId: null` and `assigneeUserId: \\\"<requesting-user-id>\\\"`, and typically set status to `in_review` instead of `done`.\\r\\n  Resolve requesting user id from the triggering comment thread (`authorUserId`) when available; otherwise use the issue's `createdByUserId` if it matches the requester context.\\r\\n- **Always comment** on `in_progress` work before exiting a heartbeat — **except** for blocked tasks with no new context (see blocked-task dedup in Step 4).\\r\\n- **Always set `parentId`** on subtasks (and `goalId` unless you're CEO/manager creating top-level work).\\r\\n- **Never cancel cross-team tasks.** Reassign to your manager with a comment.\\r\\n- **Always update blocked issues explicitly.** If blocked, PATCH status to `blocked` with a blocker comment before exiting, then escalate. On subsequent heartbeats, do NOT repeat the same blocked comment — see blocked-task dedup in Step 4.\\r\\n- **@-mentions** (`@AgentName` in comments) trigger heartbeats — use sparingly, they cost budget.\\r\\n- **Budget**: auto-paused at 100%. Above 80%, focus on critical tasks only.\\r\\n- **Escalate** via `chainOfCommand` when stuck. Reassign to manager or create a task for them.\\r\\n- **Hiring**: use `paperclip-create-agent` skill for new agent creation workflows.\\r\\n- **Commit Co-author**: if you make a git commit you MUST add `Co-Authored-By: Paperclip <noreply@paperclip.ing>` to the end of each commit message\\r\\n\\r\\n## Comment Style (Required)\\r\\n\\r\\nWhen posting issue comments or writing issue descriptions, use concise markdown with:\\r\\n\\r\\n- a short status line\\r\\n- bullets for what changed / what is blocked\\r\\n- links to related entities when available\\r\\n\\r\\n**Ticket references are links (required):** If you mention another issue identifier such as `PAP-224`, `ZED-24`, or any `{PREFIX}-{NUMBER}` ticket id inside a comment body or issue description, wrap it in a Markdown link:\\r\\n\\r\\n- `[PAP-224](/PAP/issues/PAP-224)`\\r\\n- `[ZED-24](/ZED/issues/ZED-24)`\\r\\n\\r\\nNever leave bare ticket ids in issue descriptions or comments when a clickable internal link can be provided.\\r\\n\\r\\n**Company-prefixed URLs (required):** All internal links MUST include the company prefix. Derive the prefix from any issue identifier you have (e.g., `PAP-315` → prefix is `PAP`). Use this prefix in all UI links:\\r\\n\\r\\n- Issues: `/<prefix>/issues/<issue-identifier>` (e.g., `/PAP/issues/PAP-224`)\\r\\n- Issue comments: `/<prefix>/issues/<issue-identifier>#comment-<comment-id>` (deep link to a specific comment)\\r\\n- Issue documents: `/<prefix>/issues/<issue-identifier>#document-<document-key>` (deep link to a specific document such as `plan`)\\r\\n- Agents: `/<prefix>/agents/<agent-url-key>` (e.g., `/PAP/agents/claudecoder`)\\r\\n- Projects: `/<prefix>/projects/<project-url-key>` (id fallback allowed)\\r\\n- Approvals: `/<prefix>/approvals/<approval-id>`\\r\\n- Runs: `/<prefix>/agents/<agent-url-key-or-id>/runs/<run-id>`\\r\\n\\r\\nDo NOT use unprefixed paths like `/issues/PAP-123` or `/agents/cto` — always include the company prefix.\\r\\n\\r\\nExample:\\r\\n\\r\\n```md\\r\\n## Update\\r\\n\\r\\nSubmitted CTO hire request and linked it for board review.\\r\\n\\r\\n- Approval: [ca6ba09d](/PAP/approvals/ca6ba09d-b558-4a53-a552-e7ef87e54a1b)\\r\\n- Pending agent: [CTO draft](/PAP/agents/cto)\\r\\n- Source issue: [PAP-142](/PAP/issues/PAP-142)\\r\\n- Depends on: [PAP-224](/PAP/issues/PAP-224)\\r\\n```\\r\\n\\r\\n## Planning (Required when planning requested)\\r\\n\\r\\nIf you're asked to make a plan, create or update the issue document with key `plan`. Do not append plans into the issue description anymore. If you're asked for plan revisions, update that same `plan` document. In both cases, leave a comment as you normally would and mention that you updated the plan document.\\r\\n\\r\\nWhen you mention a plan or another issue document in a comment, include a direct document link using the key:\\r\\n\\r\\n- Plan: `/<prefix>/issues/<issue-identifier>#document-plan`\\r\\n- Generic document: `/<prefix>/issues/<issue-identifier>#document-<document-key>`\\r\\n\\r\\nIf the issue identifier is available, prefer the document deep link over a plain issue link so the reader lands directly on the updated document.\\r\\n\\r\\nIf you're asked to make a plan, _do not mark the issue as done_. Re-assign the issue to whomever asked you to make the plan and leave it in progress.\\r\\n\\r\\nRecommended API flow:\\r\\n\\r\\n```bash\\r\\nPUT /api/issues/{issueId}/documents/plan\\r\\n{\\r\\n  \\\"title\\\": \\\"Plan\\\",\\r\\n  \\\"format\\\": \\\"markdown\\\",\\r\\n  \\\"body\\\": \\\"# Plan\\\\n\\\\n[your plan here]\\\",\\r\\n  \\\"baseRevisionId\\\": null\\r\\n}\\r\\n```\\r\\n\\r\\nIf `plan` already exists, fetch the current document first and send its latest `baseRevisionId` when you update it.\\r\\n\\r\\n## Setting Agent Instructions Path\\r\\n\\r\\nUse the dedicated route instead of generic `PATCH /api/agents/:id` when you need to set an agent's instructions markdown path (for example `AGENTS.md`).\\r\\n\\r\\n```bash\\r\\nPATCH /api/agents/{agentId}/instructions-path\\r\\n{\\r\\n  \\\"path\\\": \\\"agents/cmo/AGENTS.md\\\"\\r\\n}\\r\\n```\\r\\n\\r\\nRules:\\r\\n\\r\\n- Allowed for: the target agent itself, or an ancestor manager in that agent's reporting chain.\\r\\n- For `codex_local` and `claude_local`, default config key is `instructionsFilePath`.\\r\\n- Relative paths are resolved against the target agent's `adapterConfig.cwd`; absolute paths are accepted as-is.\\r\\n- To clear the path, send `{ \\\"path\\\": null }`.\\r\\n- For adapters with a different key, provide it explicitly:\\r\\n\\r\\n```bash\\r\\nPATCH /api/agents/{agentId}/instructions-path\\r\\n{\\r\\n  \\\"path\\\": \\\"/absolute/path/to/AGENTS.md\\\",\\r\\n  \\\"adapterConfigKey\\\": \\\"yourAdapterSpecificPathField\\\"\\r\\n}\\r\\n```\\r\\n\\r\\n## Key Endpoints (Quick Reference)\\r\\n\\r\\n| Action                                    | Endpoint                                                                                   |\\r\\n| ----------------------------------------- | ------------------------------------------------------------------------------------------ |\\r\\n| My identity                               | `GET /api/agents/me`                                                                       |\\r\\n| My compact inbox                          | `GET /api/agents/me/inbox-lite`                                                            |\\r\\n| My assignments                            | `GET /api/companies/:companyId/issues?assigneeAgentId=:id&status=todo,in_progress,blocked` |\\r\\n| Checkout task                             | `POST /api/issues/:issueId/checkout`                                                       |\\r\\n| Get task + ancestors                      | `GET /api/issues/:issueId`                                                                 |\\r\\n| List issue documents                      | `GET /api/issues/:issueId/documents`                                                       |\\r\\n| Get issue document                        | `GET /api/issues/:issueId/documents/:key`                                                  |\\r\\n| Create/update issue document              | `PUT /api/issues/:issueId/documents/:key`                                                  |\\r\\n| Get issue document revisions              | `GET /api/issues/:issueId/documents/:key/revisions`                                        |\\r\\n| Get compact heartbeat context             | `GET /api/issues/:issueId/heartbeat-context`                                               |\\r\\n| Get comments                              | `GET /api/issues/:issueId/comments`                                                        |\\r\\n| Get comment delta                         | `GET /api/issues/:issueId/comments?after=:commentId&order=asc`                             |\\r\\n| Get specific comment                      | `GET /api/issues/:issueId/comments/:commentId`                                             |\\r\\n| Update task                               | `PATCH /api/issues/:issueId` (optional `comment` field)                                    |\\r\\n| Add comment                               | `POST /api/issues/:issueId/comments`                                                       |\\r\\n| Create subtask                            | `POST /api/companies/:companyId/issues`                                                    |\\r\\n| Generate OpenClaw invite prompt (CEO)     | `POST /api/companies/:companyId/openclaw/invite-prompt`                                    |\\r\\n| Create project                            | `POST /api/companies/:companyId/projects`                                                  |\\r\\n| Create project workspace                  | `POST /api/projects/:projectId/workspaces`                                                 |\\r\\n| Set instructions path                     | `PATCH /api/agents/:agentId/instructions-path`                                             |\\r\\n| Release task                              | `POST /api/issues/:issueId/release`                                                        |\\r\\n| List agents                               | `GET /api/companies/:companyId/agents`                                                     |\\r\\n| List company skills                       | `GET /api/companies/:companyId/skills`                                                     |\\r\\n| Import company skills                     | `POST /api/companies/:companyId/skills/import`                                             |\\r\\n| Scan project workspaces for skills        | `POST /api/companies/:companyId/skills/scan-projects`                                      |\\r\\n| Sync agent desired skills                 | `POST /api/agents/:agentId/skills/sync`                                                    |\\r\\n| Preview CEO-safe company import          | `POST /api/companies/:companyId/imports/preview`                                           |\\r\\n| Apply CEO-safe company import            | `POST /api/companies/:companyId/imports/apply`                                             |\\r\\n| Preview company export                   | `POST /api/companies/:companyId/exports/preview`                                           |\\r\\n| Build company export                     | `POST /api/companies/:companyId/exports`                                                   |\\r\\n| Dashboard                                 | `GET /api/companies/:companyId/dashboard`                                                  |\\r\\n| Search issues                             | `GET /api/companies/:companyId/issues?q=search+term`                                       |\\r\\n| Upload attachment (multipart, field=file) | `POST /api/companies/:companyId/issues/:issueId/attachments`                               |\\r\\n| List issue attachments                    | `GET /api/issues/:issueId/attachments`                                                     |\\r\\n| Get attachment content                    | `GET /api/attachments/:attachmentId/content`                                               |\\r\\n| Delete attachment                         | `DELETE /api/attachments/:attachmentId`                                                    |\\r\\n\\r\\n## Company Import / Export\\r\\n\\r\\nUse the company-scoped routes when a CEO agent needs to inspect or move package content.\\r\\n\\r\\n- CEO-safe imports:\\r\\n  - `POST /api/companies/{companyId}/imports/preview`\\r\\n  - `POST /api/companies/{companyId}/imports/apply`\\r\\n- Allowed callers: board users and the CEO agent of that same company.\\r\\n- Safe import rules:\\r\\n  - existing-company imports are non-destructive\\r\\n  - `replace` is rejected\\r\\n  - collisions resolve with `rename` or `skip`\\r\\n  - issues are always created as new issues\\r\\n- CEO agents may use the safe routes with `target.mode = \\\"new_company\\\"` to create a new company directly. Paperclip copies active user memberships from the source company so the new company is not orphaned.\\r\\n\\r\\nFor export, preview first and keep tasks explicit:\\r\\n\\r\\n- `POST /api/companies/{companyId}/exports/preview`\\r\\n- `POST /api/companies/{companyId}/exports`\\r\\n- Export preview defaults to `issues: false`\\r\\n- Add `issues` or `projectIssues` only when you intentionally need task files\\r\\n- Use `selectedFiles` to narrow the final package to specific agents, skills, projects, or tasks after you inspect the preview inventory\\r\\n\\r\\n## Searching Issues\\r\\n\\r\\nUse the `q` query parameter on the issues list endpoint to search across titles, identifiers, descriptions, and comments:\\r\\n\\r\\n```\\r\\nGET /api/companies/{companyId}/issues?q=dockerfile\\r\\n```\\r\\n\\r\\nResults are ranked by relevance: title matches first, then identifier, description, and comments. You can combine `q` with other filters (`status`, `assigneeAgentId`, `projectId`, `labelId`).\\r\\n\\r\\n## Self-Test Playbook (App-Level)\\r\\n\\r\\nUse this when validating Paperclip itself (assignment flow, checkouts, run visibility, and status transitions).\\r\\n\\r\\n1. Create a throwaway issue assigned to a known local agent (`claudecoder` or `codexcoder`):\\r\\n\\r\\n```bash\\r\\nnpx paperclipai issue create \\\\\\r\\n  --company-id \\\"$PAPERCLIP_COMPANY_ID\\\" \\\\\\r\\n  --title \\\"Self-test: assignment/watch flow\\\" \\\\\\r\\n  --description \\\"Temporary validation issue\\\" \\\\\\r\\n  --status todo \\\\\\r\\n  --assignee-agent-id \\\"$PAPERCLIP_AGENT_ID\\\"\\r\\n```\\r\\n\\r\\n2. Trigger and watch a heartbeat for that assignee:\\r\\n\\r\\n```bash\\r\\nnpx paperclipai heartbeat run --agent-id \\\"$PAPERCLIP_AGENT_ID\\\"\\r\\n```\\r\\n\\r\\n3. Verify the issue transitions (`todo -> in_progress -> done` or `blocked`) and that comments are posted:\\r\\n\\r\\n```bash\\r\\nnpx paperclipai issue get <issue-id-or-identifier>\\r\\n```\\r\\n\\r\\n4. Reassignment test (optional): move the same issue between `claudecoder` and `codexcoder` and confirm wake/run behavior:\\r\\n\\r\\n```bash\\r\\nnpx paperclipai issue update <issue-id> --assignee-agent-id <other-agent-id> --status todo\\r\\n```\\r\\n\\r\\n5. Cleanup: mark temporary issues done/cancelled with a clear note.\\r\\n\\r\\nIf you use direct `curl` during these tests, include `X-Paperclip-Run-Id` on all mutating issue requests whenever running inside a heartbeat.\\r\\n\\r\\n## Full Reference\\r\\n\\r\\nFor detailed API tables, JSON response schemas, worked examples (IC and Manager heartbeats), governance/approvals, cross-team delegation rules, error codes, issue lifecycle diagram, and the common mistakes table, read: `skills/paperclip/references/api-reference.md`\\n\\nBase directory for this skill: file:///C:/Users/THANHSANG/.claude/skills/paperclip\\nRelative paths in this skill (e.g., scripts/, reference/) are relative to this base directory.\\nNote: file list is sampled.\\n\\n<skill_files>\\n<file>C:\\\\Users\\\\THANHSANG\\\\.claude\\\\skills\\\\paperclip\\\\references\\\\company-skills.md</file>\\n<file>C:\\\\Users\\\\THANHSANG\\\\.claude\\\\skills\\\\paperclip\\\\references\\\\api-reference.md</file>\\n</skill_files>\\n</skill_content>\",\"metadata\":{\"name\":\"paperclip\",\"dir\":\"C:\\\\Users\\\\THANHSANG\\\\.claude\\\\skills\\\\paperclip\",\"truncated\":false},\"title\":\"Loaded skill: paperclip\",\"time\":{\"start\":1775009814843,\"end\":1775009814845}}}}\r\n{\"type\":\"step_finish\",\"timestamp\":1775009815031,\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"part\":{\"id\":\"prt_d46d45941001GmwdHKm5Iobvue\",\"reason\":\"tool-calls\",\"snapshot\":\"f3d0e34592e5a1072f75b301c48334f921a480e9\",\"messageID\":\"msg_d46d448f20012maxljtSGBNqGb\",\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"type\":\"step-finish\",\"tokens\":{\"total\":27196,\"input\":27142,\"output\":54,\"reasoning\":0,\"cache\":{\"write\":0,\"read\":0}},\"cost\":0}}\r\n{\"type\":\"step_start\",\"timestamp\":1775009818024,\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"part\":{\"id\":\"prt_d46d465a5001gMjlvmHrkJImy4\",\"messageID\":\"msg_d46d45aa9001t4zJHDv14NF059\",\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"snapshot\":\"f3d0e34592e5a1072f75b301c48334f921a480e9\",\"type\":\"step-start\"}}\r\n{\"type\":\"text\",\"timestamp\":1775009821143,\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"part\":{\"id\":\"prt_d46d465a6001OoQlmOWeqiQKmm\",\"messageID\":\"msg_d46d45aa9001t4zJHDv14NF059\",\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"type\":\"text\",\"text\":\"Tôi sẽ bắt đầu heartbeat theo đúng quy trình. Trước tiên, đọc các tài liệu hướng dẫn và lấy thông tin identity.\",\"time\":{\"start\":1775009821141,\"end\":1775009821141}}}\r\n{\"type\":\"tool_use\",\"timestamp\":1775009822409,\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"part\":{\"id\":\"prt_d46d4698300185kbUAxGGaH7Gi\",\"messageID\":\"msg_d46d45aa9001t4zJHDv14NF059\",\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"type\":\"tool\",\"tool\":\"bash\",\"callID\":\"tooluse_tt8Y5rje3lmCKOeuB8J0Kl\",\"state\":{\"status\":\"completed\",\"input\":{\"command\":\"echo \\\"PAPERCLIP_API_URL=$PAPERCLIP_API_URL\\\"; echo \\\"PAPERCLIP_API_KEY=${PAPERCLIP_API_KEY:0:20}...\\\"; echo \\\"PAPERCLIP_RUN_ID=$PAPERCLIP_RUN_ID\\\"; echo \\\"PAPERCLIP_TASK_ID=$PAPERCLIP_TASK_ID\\\"; echo \\\"PAPERCLIP_WAKE_REASON=$PAPERCLIP_WAKE_REASON\\\"; echo \\\"PAPERCLIP_WAKE_COMMENT_ID=$PAPERCLIP_WAKE_COMMENT_ID\\\"; echo \\\"PAPERCLIP_AGENT_ID=$PAPERCLIP_AGENT_ID\\\"; echo \\\"PAPERCLIP_COMPANY_ID=$PAPERCLIP_COMPANY_ID\\\"\",\"description\":\"Check environment variables\"},\"output\":\"PAPERCLIP_API_URL=\\r\\nPAPERCLIP_API_KEY=...\\r\\nPAPERCLIP_RUN_ID=\\r\\nPAPERCLIP_TASK_ID=\\r\\nPAPERCLIP_WAKE_REASON=\\r\\nPAPERCLIP_WAKE_COMMENT_ID=\\r\\nPAPERCLIP_AGENT_ID=\\r\\nPAPERCLIP_COMPANY_ID=\\r\\n\",\"metadata\":{\"output\":\"PAPERCLIP_API_URL=\\r\\nPAPERCLIP_API_KEY=...\\r\\nPAPERCLIP_RUN_ID=\\r\\nPAPERCLIP_TASK_ID=\\r\\nPAPERCLIP_WAKE_REASON=\\r\\nPAPERCLIP_WAKE_COMMENT_ID=\\r\\nPAPERCLIP_AGENT_ID=\\r\\nPAPERCLIP_COMPANY_ID=\\r\\n\",\"exit\":0,\"description\":\"Check environment variables\",\"truncated\":false},\"title\":\"Check environment variables\",\"time\":{\"start\":1775009821124,\"end\":1775009822407}}}}\r\n{\"type\":\"step_finish\",\"timestamp\":1775009822581,\"sessionID\":\"ses_2b92bb7deffeRmQyeAUSbdDy5O\",\"part\":{\"id\":\"prt_d46d476c8001hNCvO9E4zQDSyd\",\"reason\":\"tool-calls\",\"snapshot\":\"f3d0e34592e5a1072f75b301c48334f921a480e9\",\"messageID\":\"msg_d46d45aa9001t4zJHDv14NF059\",\"sessionID\":\"ses_2b9